queries.query:
SELECT DISTINCT ?form ?group ?gloss
FROM <GRAPH>
WHERE {
  ?label skosxl:literalForm ?form ;
         dia:gloss ?gloss ;
         dcterms:spatial ?g .
  OPTIONAL { ?g dcterms:title ?group }
  OPTIONAL { ?label dia:variantForm ?variant }
  FILTER(REGEX(?form, "김치", "i") || REGEX(?variant, "김치", "i") || REGEX(?gloss, "김치", "i"))
}
ORDER BY ?group ?form

SELECT ?object ?group ?form
FROM <GRAPH>
WHERE {
  ?label dia:denotes ?c ;
         skosxl:literalForm ?form ;
         dcterms:spatial ?g .
  ?c skos:prefLabel ?object .
  OPTIONAL { ?g dcterms:title ?group }
}
ORDER BY ?object ?group ?form

SELECT ?group ?scene ?period
FROM <GRAPH>
WHERE {
  ?s dia:aspect "먹는 것" ;
     dcterms:title ?scene ;
     dcterms:spatial ?g .
  ?g a foaf:Group .
  OPTIONAL { ?g dcterms:title ?group }
  OPTIONAL { ?s dcterms:temporal ?period }
}
ORDER BY ?group ?scene

SELECT ?group ?aspect (COUNT(?s) AS ?scenes)
FROM <GRAPH>
WHERE {
  ?s dia:aspect ?aspect ;
     dcterms:spatial ?g .
  ?g a foaf:Group ;
     dcterms:title ?group .
}
GROUP BY ?group ?aspect
ORDER BY ?group ?aspect

SELECT ?scene ?source ?author
FROM <GRAPH>
WHERE {
  ?s a dia:Scene ;
     dcterms:title ?scene ;
     dcterms:source ?ref .
  OPTIONAL { ?ref dcterms:title ?source }
  OPTIONAL { ?ref dcterms:creator ?author }
}
ORDER BY ?scene ?source

SELECT ?page ?id
FROM <GRAPH>
WHERE {
  ?s dia:citation ?page ;
     rico:identifier ?id .
  FILTER(REGEX(?page, "^kwon2020:", "i"))
}
ORDER BY ?page ?id

SELECT ?language ?form ?group ?gloss
FROM <GRAPH>
WHERE {
  ?label skosxl:literalForm ?form ;
         dia:sourceLanguage ?language ;
         dia:gloss ?gloss ;
         dcterms:spatial ?g .
  OPTIONAL { ?g dcterms:title ?group }
  FILTER(?language != "kor")
}
ORDER BY ?language ?form

SELECT ?form ?gloss ?etymology
FROM <GRAPH>
WHERE {
  ?label skosxl:literalForm ?form ;
         dia:gloss ?gloss ;
         dia:etymologyNote ?etymology .
}
ORDER BY ?form

SELECT ?parent ?place ?lat ?long ?note
FROM <GRAPH>
WHERE {
  ?p a dcterms:Location ;
     dcterms:title ?place .
  OPTIONAL { ?p dcterms:isPartOf ?pp . ?pp dcterms:title ?parent }
  OPTIONAL { ?p geo:lat ?lat }
  OPTIONAL { ?p geo:long ?long }
  OPTIONAL { ?p skos:editorialNote ?note }
}
ORDER BY ?parent ?place

SELECT ?id ?note
FROM <GRAPH>
WHERE {
  ?s skos:editorialNote ?note ;
     rico:identifier ?id .
  FILTER(REGEX(?note, "^확인 필요", "i"))
}
ORDER BY ?id

SELECT ?resource ?value ?page
WHERE {
  ?st dia:basis "해석" ;
      rdf:subject ?item ;
      rdf:object ?value .
  ?item rdfs:label ?resource .
  OPTIONAL { ?st prov:atLocation ?page }
}
ORDER BY ?resource ?page

SELECT ?sentence ?basis ?page
WHERE {
  ?st rdf:predicate dcterms:description ;
      rdf:subject ?item ;
      rdf:object ?sentence .
  ?item rdfs:label ?resource .
  OPTIONAL { ?st dia:basis ?basis }
  OPTIONAL { ?st prov:atLocation ?page }
  FILTER(REGEX(?resource, "고려인의 밥상", "i"))
}
ORDER BY ?page
